#[ignore = "go-parity-gap: semi-to-inner rewrite rule belongs to the unported rule pipeline"]
fn semi_join_to_inner_when_inner_side_is_unique() {}

/// GO PORT of `pkg/planner/core/casetest/physicalplantest/
