#[test]
#[ignore = "go-parity-gap: needs SQL parsing plus metadef schema classification"]
fn filter_sql_accessing_system_tables_keeps_only_user_table_queries() {}

/// GO PORT of `pkg/planner/indexadvisor/utils_test.go:117
